// <npm-compat-chart src="...">
//
// Renders the committed npm-package-compatibility summary
// (benchmarks/results/npm-compat.json, generated by
// scripts/generate-npm-compat-report.mjs): a dashboard-style metrics row plus
// one card per package — compile/validate status, test pass rate (the
// package's own real test suite where one exists, otherwise a labeled
// differential-ops count — never conflated), and a head-to-head perf
// comparison of the compiled Wasm export against the SAME pinned package
// running natively under Node.
//
// Same fetch-at-runtime convention as t262-charts.js / trend-chart.js /
// perf-benchmark-chart.js — no build-time templating. Styling matches
// website/dashboard/index.html (dense, sharp-cornered, minimal chrome).

class NpmCompatChart extends HTMLElement {
  static get observedAttributes() {
    return ["src"];
  }

  connectedCallback() {
    this.attachShadow({ mode: "open" });
    this._load();
  }

  attributeChangedCallback() {
    if (this.isConnected && this.shadowRoot) this._load();
  }

  async _load() {
    const src = this.getAttribute("src");
    if (!src) return;
    this._renderLoading();
    try {
      const res = await fetch(src);
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      this._render(await res.json());
    } catch (err) {
      this._renderError(err);
    }
  }

  _renderLoading() {
    this.shadowRoot.innerHTML = `${this._styles()}<div class="msg">Loading…</div>`;
  }

  _renderError(err) {
    const m = err && err.message ? err.message : String(err);
    this.shadowRoot.innerHTML = `${this._styles()}<div class="msg error">Failed to load: ${this._esc(m)}</div>`;
  }

  _esc(s) {
    const d = document.createElement("div");
    d.textContent = s;
    return d.innerHTML;
  }

  _fmtDate(iso) {
    if (!iso) return "";
    const d = new Date(iso);
    if (Number.isNaN(d.valueOf())) return "";
    return d.toISOString().slice(0, 10);
  }

  _fmtMs(us) {
    if (us == null) return "—";
    const ms = us / 1000;
    if (ms >= 1000) return `${(ms / 1000).toFixed(2)}s`;
    if (ms >= 1) return `${ms.toFixed(1)}ms`;
    if (us < 0.1) return `${(us * 1000).toFixed(1)}ns`;
    if (us < 1) return `${us.toFixed(2)}µs`;
    return `${us.toFixed(1)}µs`;
  }

  // ratio = nodeUs / wasmUs. >1 => wasm faster. <1 => node faster.
  _perfLabel(ratio) {
    if (ratio == null) return { text: "—", cls: "" };
    const factor = ratio >= 1 ? ratio : 1 / ratio;
    const digits = factor >= 100 ? 0 : factor >= 10 ? 1 : 2;
    const formatted = factor.toLocaleString("en-US", {
      minimumFractionDigits: 0,
      maximumFractionDigits: digits,
    });
    return ratio >= 1 ? { text: `${formatted}× faster`, cls: "good" } : { text: `${formatted}× slower`, cls: "bad" };
  }

  _row(label, valueHtml, cls) {
    return `<div class="row"><span class="k">${this._esc(label)}</span><span class="v ${cls || ""}">${valueHtml}</span></div>`;
  }

  _operationLabel(sampleOp) {
    const value = String(sampleOp ?? "");
    if (/parse\(.*226KB dist bundle/i.test(value)) return "Parse the 226 KB Acorn bundle";
    if (/op_two_strings/i.test(value)) return "Join two class names";
    if (/parseCookie\(8-pair header\)/i.test(value)) return "Parse an 8-pair cookie header";
    return value
      .replace(/\s*\([^)]*(host-owned arguments|driver compiled to Wasm)[^)]*\)\s*/gi, " ")
      .replace(/\.body\.length\b/g, "")
      .replace(/\s+/g, " ")
      .trim();
  }

  _lane(lane, label) {
    if (!lane) {
      return `
        <div class="lane unavailable">
          <span class="lane-name">${this._esc(label)}</span>
          <span class="lane-result muted">Not measured</span>
        </div>`;
    }
    if (lane.status && lane.status !== "measured") {
      const detail = lane.diagnostic ?? lane.reason ?? lane.status;
      return `
        <div class="lane unavailable">
          <span class="lane-name">${this._esc(label)}</span>
          <span class="lane-result muted">${this._esc(detail)}</span>
        </div>`;
    }
    const result = this._perfLabel(lane.ratio);
    return `
      <div class="lane">
        <div class="lane-top">
          <span class="lane-name">${this._esc(label)}</span>
          <strong class="lane-result ${result.cls}">${result.text}</strong>
        </div>
        <div class="lane-times mono">
          <span>${this._fmtMs(lane.wasmUs)} Wasm</span>
          <span>${this._fmtMs(lane.nodeUs)} Node</span>
        </div>
      </div>`;
  }

  _bindPerfControls() {
    this.shadowRoot.querySelectorAll(".perf-block").forEach((perf) => {
      const setPressed = (attribute, value) => {
        perf.querySelectorAll(`button[${attribute}]`).forEach((button) => {
          button.setAttribute("aria-pressed", String(button.getAttribute(attribute) === value));
        });
      };
      perf.querySelectorAll("button[data-input-value]").forEach((button) => {
        button.addEventListener("click", () => {
          const value = button.getAttribute("data-input-value");
          perf.dataset.input = value;
          setPressed("data-input-value", value);
        });
      });
      perf.querySelectorAll("button[data-target-value]").forEach((button) => {
        button.addEventListener("click", () => {
          const value = button.getAttribute("data-target-value");
          perf.dataset.target = value;
          setPressed("data-target-value", value);
        });
      });
    });
  }

  _card(pkg) {
    const compiles = pkg.compile?.success;
    const validates = pkg.validation?.validates;

    const badge = (ok, label) =>
      `<span class="badge ${ok === true ? "ok" : ok === false ? "bad" : ""}">${this._esc(label)}</span>`;

    // Tests — the "own test suite" vs "differential ops" distinction is
    // load-bearing, so it is the row's own label, never blurred into one number.
    let tests;
    if (!pkg.tests) {
      const reason = compiles ? "runtime not verified" : "compile blocked";
      tests = this._row("tests", `<span class="muted">n/a — ${reason}</span>`);
    } else {
      const { kind, passed, total, passRatePct } = pkg.tests;
      const pct = passRatePct != null ? passRatePct : total ? ((passed / total) * 100).toFixed(1) : null;
      const label = kind === "official-suite" ? "own test suite" : "differential ops";
      tests = this._row(
        "tests",
        `<span class="mono">${passed}/${total}</span>${pct != null ? ` <span class="muted">${pct}%</span>` : ""} <span class="tag">${this._esc(label)}</span>`,
      );
    }

    // Perf — compact lane names; full methodology lives below the dashboard.
    let perf;
    if (!pkg.perf) {
      perf = this._row("perf vs node", `<span class="muted">not measured</span>`);
    } else {
      const lanes = pkg.perf.lanes ?? { jsHost: pkg.perf };
      const operation = this._operationLabel(pkg.perf.sampleOp);
      perf = `
        <div class="perf-block" data-input="dynamic" data-target="host">
          <div class="section-title">
            <span>Performance vs Node</span>
            ${operation ? `<span class="operation" title="${this._esc(pkg.perf.sampleOp)}">${this._esc(operation)}</span>` : ""}
          </div>
          <div class="benchmark-controls">
            <div class="toggle-group" aria-label="Input kind">
              <button type="button" data-input-value="dynamic" aria-pressed="true">Dynamic</button>
              <button type="button" data-input-value="static" aria-pressed="false">Static</button>
            </div>
            <div class="toggle-group target-toggle" aria-label="Wasm runtime">
              <button type="button" data-target-value="host" aria-pressed="true">JS host</button>
              <button type="button" data-target-value="standalone" aria-pressed="false">Standalone</button>
            </div>
          </div>
          <div class="perf-view dynamic-host">${this._lane(lanes.jsHost, "JS host")}</div>
          <div class="perf-view dynamic-standalone">${this._lane(lanes.standaloneDynamic, "Standalone")}</div>
          <div class="perf-view static-standalone">${this._lane(lanes.standalone, "Standalone")}</div>
          <p class="static-note">Compiler-visible input · standalone Wasm</p>
        </div>`;
    }

    const bugs = (pkg.knownBugs ?? []).length
      ? this._row(
          "open issues",
          pkg.knownBugs
            .map(
              (b) =>
                `<a href="https://github.com/loopdive/js2/issues/${b.issue}" target="_blank" rel="noopener" title="${this._esc(b.summary)}">#${b.issue}</a>`,
            )
            .join(" "),
        )
      : "";

    return `
      <div class="card">
        <div class="card-top">
          <span class="name">${this._esc(pkg.name)}</span>
          <span class="ver mono">v${this._esc(pkg.version)}</span>
          <a class="issue" href="https://github.com/loopdive/js2/issues/${pkg.issue}" target="_blank" rel="noopener">#${pkg.issue}</a>
        </div>
        <div class="badges">${badge(compiles, "compiles")}${badge(validates, "validates")}</div>
        <div class="rows">${tests}${perf}${bugs}</div>
        <div class="entry mono">${this._esc(pkg.entryFile)}</div>
      </div>`;
  }

  _render(data) {
    const pkgs = data.packages ?? [];
    const compiling = pkgs.filter((p) => p.compile?.success).length;
    const validating = pkgs.filter((p) => p.validation?.validates).length;
    const metric = (v, l) => `<div class="metric"><span class="value">${v}</span><span class="label">${l}</span></div>`;

    this.shadowRoot.innerHTML = `
      ${this._styles()}
      <div class="metrics">
        ${metric(pkgs.length, "packages")}
        ${metric(`${compiling}/${pkgs.length}`, "compile")}
        ${metric(`${validating}/${pkgs.length}`, "validate")}
        ${metric(this._fmtDate(data.generatedAt) || "—", "measured")}
      </div>
      <div class="cards">${pkgs.map((p) => this._card(p)).join("")}</div>
      ${data.note ? `<p class="note">${this._esc(data.note)}</p>` : ""}
    `;
    this._bindPerfControls();
  }

  _styles() {
    return `
      <style>
        :host {
          display: block;
          font-family: var(--font, Inter, ui-sans-serif, system-ui, sans-serif);
          color: var(--text, #fff);
        }
        .mono { font-family: var(--mono, "JetBrains Mono", "SF Mono", monospace); }
        .muted { color: var(--text-muted, rgba(255,255,255,0.46)); }
        .good { color: var(--green, #4ade80); }
        .bad { color: var(--red, #f87171); }
        .msg { padding: 48px; text-align: center; color: var(--text-muted, rgba(255,255,255,0.46)); }
        .msg.error { color: var(--red, #f87171); }

        /* Dashboard-style metrics row: big number, tiny uppercase label, no box */
        .metrics {
          display: flex;
          justify-content: space-evenly;
          flex-wrap: wrap;
          gap: 16px;
          padding: 22px 0 26px;
        }
        .metric { display: flex; flex-direction: column; align-items: center; white-space: nowrap; }
        .metric .value {
          font-size: 28px;
          font-weight: 700;
          line-height: 1;
          letter-spacing: -0.05em;
          margin-bottom: 8px;
        }
        .metric .label {
          font-size: 10px;
          color: rgba(255, 255, 255, 0.35);
          text-transform: uppercase;
          letter-spacing: 0.08em;
        }

        .cards {
          display: grid;
          grid-template-columns: repeat(2, minmax(0, 1fr));
          gap: 1px;
          background: var(--border, rgba(255,255,255,0.12));
          border: 1px solid var(--border, rgba(255,255,255,0.12));
        }
        .card {
          background: var(--bg, #060a14);
          padding: 18px 20px 16px;
          min-width: 0;
        }
        .card:last-child:nth-child(odd) {
          grid-column: 1 / -1;
        }
        .card-top { display: flex; align-items: baseline; gap: 8px; margin-bottom: 10px; }
        .card-top .name { font-size: 15px; font-weight: 600; }
        .card-top .ver { font-size: 11px; color: var(--text-muted, rgba(255,255,255,0.46)); }
        .card-top .issue {
          margin-left: auto;
          font-size: 11px;
          color: var(--text-muted, rgba(255,255,255,0.46));
          text-decoration: none;
        }
        .card-top .issue:hover { text-decoration: underline; }

        .badges { display: flex; gap: 6px; margin-bottom: 10px; }
        .badge {
          font-size: 10px;
          text-transform: uppercase;
          letter-spacing: 0.06em;
          padding: 2px 6px;
          border: 1px solid currentColor;
          color: var(--text-muted, rgba(255,255,255,0.46));
        }
        .badge.ok { color: var(--green, #4ade80); }
        .badge.bad { color: var(--red, #f87171); }

        .rows { display: flex; flex-direction: column; }
        .row {
          display: flex;
          justify-content: space-between;
          align-items: baseline;
          gap: 10px;
          font-size: 12px;
          padding: 5px 0;
          border-bottom: 1px solid rgba(255, 255, 255, 0.06);
        }
        .row:last-child { border-bottom: none; }
        .row .k {
          color: rgba(255, 255, 255, 0.35);
          text-transform: uppercase;
          font-size: 10px;
          letter-spacing: 0.06em;
          white-space: nowrap;
        }
        .row .v { text-align: right; }
        .row .v a { color: var(--accent, #6c8aff); text-decoration: none; }
        .row .v a:hover { text-decoration: underline; }
        .tag {
          font-size: 9px;
          text-transform: uppercase;
          letter-spacing: 0.06em;
          color: rgba(255, 255, 255, 0.35);
          border: 1px solid rgba(255, 255, 255, 0.14);
          padding: 1px 4px;
          margin-left: 2px;
        }
        .perf-block {
          padding: 12px 0 10px;
          border-bottom: 1px solid rgba(255, 255, 255, 0.06);
        }
        .section-title {
          display: flex;
          justify-content: space-between;
          gap: 16px;
          margin-bottom: 8px;
          color: rgba(255, 255, 255, 0.35);
          text-transform: uppercase;
          font-size: 10px;
          letter-spacing: 0.06em;
        }
        .section-title .operation {
          color: var(--text-muted, rgba(255,255,255,0.46));
          text-transform: none;
          letter-spacing: 0;
          overflow: hidden;
          text-overflow: ellipsis;
          white-space: nowrap;
        }
        .benchmark-controls {
          display: flex;
          justify-content: space-between;
          gap: 12px;
          margin-bottom: 8px;
        }
        .toggle-group {
          display: inline-flex;
          padding: 2px;
          background: rgba(255, 255, 255, 0.035);
          border: 1px solid rgba(255, 255, 255, 0.08);
        }
        .toggle-group button {
          appearance: none;
          border: 0;
          padding: 4px 8px;
          background: transparent;
          color: rgba(255, 255, 255, 0.4);
          font: inherit;
          font-size: 9px;
          line-height: 1;
          cursor: pointer;
        }
        .toggle-group button:hover {
          color: var(--text, #fff);
        }
        .toggle-group button[aria-pressed="true"] {
          background: rgba(255, 255, 255, 0.1);
          color: var(--text, #fff);
        }
        .perf-view,
        .static-note {
          display: none;
        }
        .perf-block[data-input="dynamic"][data-target="host"] .dynamic-host,
        .perf-block[data-input="dynamic"][data-target="standalone"] .dynamic-standalone,
        .perf-block[data-input="static"] .static-standalone {
          display: block;
        }
        .perf-block[data-input="static"] .target-toggle {
          visibility: hidden;
        }
        .perf-block[data-input="static"] .static-note {
          display: block;
        }
        .static-note {
          margin: 6px 0 0;
          color: rgba(255, 255, 255, 0.3);
          font-size: 9px;
        }
        .lane {
          min-width: 0;
          padding: 9px 10px 8px;
          background: rgba(255, 255, 255, 0.035);
          border: 1px solid rgba(255, 255, 255, 0.07);
        }
        .lane.unavailable {
          display: flex;
          flex-direction: column;
          gap: 5px;
        }
        .lane-top {
          display: flex;
          align-items: baseline;
          justify-content: space-between;
          gap: 8px;
        }
        .lane-name {
          color: var(--text-muted, rgba(255,255,255,0.46));
          font-size: 10px;
          white-space: nowrap;
        }
        .lane-result {
          font-size: 12px;
          white-space: nowrap;
        }
        .lane-times {
          display: flex;
          justify-content: space-between;
          gap: 8px;
          margin-top: 5px;
          color: rgba(255, 255, 255, 0.35);
          font-size: 9px;
          white-space: nowrap;
        }
        .entry {
          margin-top: 10px;
          font-size: 10px;
          color: rgba(255, 255, 255, 0.3);
        }
        .note {
          margin-top: 18px;
          font-size: 11px;
          color: var(--text-muted, rgba(255,255,255,0.46));
          max-width: 900px;
        }

        @media (max-width: 1100px) {
          .cards { grid-template-columns: 1fr; }
          .card:last-child:nth-child(odd) { grid-column: auto; }
        }
        @media (max-width: 720px) {
          .card { padding: 16px; }
          .lane-times { justify-content: flex-start; }
          .section-title { flex-direction: column; gap: 3px; }
          .benchmark-controls { flex-wrap: wrap; }
        }
      </style>
    `;
  }
}

customElements.define("npm-compat-chart", NpmCompatChart);
